.call-group-participant {
  display: flex; min-height: 150px; flex-direction: column; align-items: center; justify-content: center; gap: 7px;
  border-radius: 9px; color: #f2f5f0; background: #26372f;
}
.call-group-participant strong { font-size: var(--type-body-lg); }
.call-group-participant span { color: #c8d2ca; font-size: var(--type-small); }
.call-participant-list { display: flex; flex-wrap: wrap; gap: 5px; padding: 7px 12px; border-top: 1px solid #e8ece5; }
.call-participant-list span { padding: 4px 6px; border-radius: 10px; color: #647267; background: #f0f3ee; font-size: var(--type-caption); }
.call-local-camera-status { position: absolute; right: 16px; bottom: 16px; display: flex; align-items: center; gap: 5px; margin: 0; padding: 6px 8px; border-radius: 6px; color: #e5ebe5; background: rgba(0, 0, 0, .42); font-size: var(--type-small); }
.voice-room-dialog { width: min(1080px, calc(100vw - 32px)); height: min(760px, calc(100dvh - 32px)); max-height: none; border-color: #2d3b33; background: #111a15; }
.voice-room-dialog .call-dialog-header { border-color: #2b3930; background: #111a15; }
