  .incoming-call-banner strong { color: #f3f6f2; font-size: var(--type-heading-sm); }
  .incoming-call-banner small { color: #c6d1c8; font-size: var(--type-body-lg); }
  .incoming-call-banner > button { width: min(280px, 100%); min-height: 48px; border-radius: 10px; font-size: var(--type-body-lg); touch-action: manipulation; }
  .incoming-call-banner .decline-call-button { order: 1; }
  .call-dialog { max-height: calc(100svh - 24px); }
  .call-media-stage { min-height: 240px; padding: 8px; }
  .call-video-local { right: 18px; bottom: 84px; }
