  .voice-room-stage { grid-template-columns: repeat(auto-fit, minmax(min(145px, 100%), 1fr)); grid-auto-rows: minmax(125px, 1fr); gap: 8px; padding: 12px; }
  .call-voice-participant { min-height: 125px; padding: 9px; }
  .avatar.call-voice-avatar { width: 56px; height: 56px; }
