.message-composer .voice-record-button,
.message-composer .voice-recorder button,
.message-composer .voice-preview button {
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 10px;
  color: #50695a;
  background: #edf2ed;
  cursor: pointer;
  transition: color .15s ease, background .15s ease, border-color .15s ease, transform .15s ease;
}
.message-composer .voice-record-button:hover:not(:disabled),
.message-composer .voice-recorder button:hover,
.message-composer .voice-preview button:hover:not(:disabled) {
  border-color: #d6e1d5;
  color: #254b38;
  background: #e2ebe1;
}
.message-composer .voice-record-button:disabled,
.message-composer .voice-preview button:disabled { cursor: default; opacity: .5; }
.message-composer .voice-recorder {
  display: flex;
  width: min(250px, 48vw);
  min-width: 0;
  height: 38px;
  box-sizing: border-box;
  align-items: center;
  gap: 7px;
  padding: 0 5px;
  border: 1px solid #ead8d5;
  border-radius: 12px;
  color: #536359;
  background: #fbf7f6;
}
.message-composer .voice-recorder button { width: 30px; height: 30px; border-radius: 9px; }
.message-composer .voice-recorder .voice-recorder-toggle { color: #6c514b; background: #f2e7e4; }
.message-composer .voice-recorder .voice-recorder-stop { color: #fff; background: #a8473e; }
.message-composer .voice-recorder .voice-recorder-stop:hover { border-color: #963d36; color: #fff; background: #963d36; }
.voice-record-indicator { width: 8px; height: 8px; flex: 0 0 auto; border-radius: 50%; background: #cf5147; animation: voice-record-pulse 1.4s ease-out infinite; }
.voice-recorder[data-paused="true"] .voice-record-indicator { background: #bd8842; animation: none; }
.voice-recorder-state { flex: 0 0 auto; color: #7b615a; font-size: var(--type-caption); font-weight: 650; }
.message-composer .voice-recorder-time { color: #35483c; font-size: var(--type-small); font-variant-numeric: tabular-nums; }
.message-composer .voice-live-wave { min-width: 24px; height: 22px; gap: 2px; color: #bd6258; }
.message-composer .voice-live-wave i { width: 3px; border-radius: 3px; opacity: .72; }
.message-composer .voice-recorder[data-paused="true"] .voice-live-wave { color: #ac8b5d; }
.message-composer .voice-preview {
  display: flex;
  min-height: 48px;
  align-items: center;
  gap: 9px;
  margin: 2px 9px 3px;
  padding: 5px 7px;
  border: 1px solid var(--color-border);
  border-radius: 13px;
  color: var(--color-text);
  background: var(--color-surface-subtle);
}
.message-composer .voice-preview .voice-preview-play { width: 36px; height: 36px; border-radius: 11px; color: #fff; background: #315b43; }
.message-composer .voice-preview .voice-preview-play:hover { border-color: #254b38; color: #fff; background: #254b38; }
.message-composer .voice-preview .voice-wave { min-width: 40px; height: 26px; color: #587c60; }
.message-composer .voice-preview .voice-wave i { width: 3px; border-radius: 3px; opacity: .7; }
.message-composer .voice-preview .voice-preview-time { min-width: 32px; color: var(--color-text-secondary); font-size: var(--type-small); text-align: right; }
.message-composer .voice-preview .voice-preview-delete { width: 34px; height: 34px; color: #8c5b54; background: transparent; }
.message-composer .voice-preview .voice-preview-delete:hover { border-color: #eed7d2; color: #a44439; background: #fbefed; }
.message-composer .voice-preview .voice-preview-send { width: 36px; height: 36px; border-radius: 11px; color: #fff; background: #315b43; }
.message-composer .voice-preview .voice-preview-send:hover:not(:disabled) { border-color: #254b38; color: #fff; background: #254b38; }
@keyframes voice-record-pulse { 50% { box-shadow: 0 0 0 4px rgba(207, 81, 71, .14); } }

:root[data-theme="dark"] .message-composer .voice-record-button,
