.incoming-call-banner {
  position: fixed; z-index: 9; right: 20px; bottom: 18px; display: flex; align-items: center; gap: 9px;
  padding: 11px 13px; border: 1px solid #dfe7dd; border-radius: 12px; background: var(--color-canvas);
