.call-overlay { z-index: 25; background: rgba(14, 30, 23, .58); }
.call-dialog {
  display: flex; width: min(740px, 100%); max-height: min(650px, calc(100svh - 32px));
  flex-direction: column; overflow: hidden; border: 1px solid #e3e9e1; border-radius: 15px;
  background: var(--color-canvas); box-shadow: 0 20px 70px rgba(10, 26, 17, .32);
}
.call-dialog-header { display: flex; min-height: 64px; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 17px; border-bottom: 1px solid #e8ece5; }
.call-dialog-header .eyebrow { margin-bottom: 4px; font-size: var(--type-caption); }
.call-dialog-header h2 { margin: 0; color: var(--color-text); font-size: var(--type-subtitle); font-weight: 600; }
.call-connection { display: flex; align-items: center; gap: 5px; color: #919b93; font-size: var(--type-small); }
.call-connection i { width: 6px; height: 6px; border-radius: 50%; background: #c6a36f; }
.call-connection.is-connected i { background: #6d9d6a; }
.call-media-stage {
  position: relative; display: grid; min-height: 300px; flex: 1; place-items: center; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr));
  gap: 8px; overflow: auto; padding: 14px; color: #879188; background: #15251e; text-align: center; font-size: var(--type-body-xs);
}
.call-media-stage.audio-only { min-height: 230px; }
.call-video-tile { width: 100%; max-height: 440px; aspect-ratio: 16 / 10; border-radius: 9px; background: #26372f; object-fit: cover; }
.call-video-local { position: absolute; right: 26px; bottom: 88px; width: min(180px, 28%); border: 1px solid rgba(255,255,255,.5); box-shadow: 0 5px 18px rgba(0,0,0,.25); }
.call-audio-track { position: absolute; width: 1px; height: 1px; opacity: 0; }
.call-error { max-width: 340px; color: #f1c6bd; line-height: 1.6; }
.call-controls { display: flex; min-height: 57px; align-items: center; justify-content: center; gap: 8px; padding: 8px; border-top: 1px solid #e8ece5; }
.call-controls button:disabled { cursor: wait; opacity: .55; }
.call-controls button { display: inline-flex; align-items: center; gap: 5px; }
.call-controls .call-end-button { align-items: center; gap: 5px; }
.call-waiting { max-width: 250px; }
.call-peer-status { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 10px; pointer-events: none; }
.call-peer-status strong { color: #f2f5f0; font-size: var(--type-title); font-weight: 600; }
.call-peer-status > span { display: flex; align-items: center; gap: 12px; color: #d2dad3; font-size: var(--type-label); }
.call-peer-status > span > svg { margin-right: -8px; }
.call-group-participant {
  display: flex; min-height: 150px; flex-direction: column; align-items: center; justify-content: center; gap: 7px;
  border-radius: 9px; color: #f2f5f0; background: #26372f;
}
.call-group-participant strong { font-size: var(--type-body-lg); }
.call-group-participant span { color: #c8d2ca; font-size: var(--type-small); }
.call-participant-list { display: flex; flex-wrap: wrap; gap: 5px; padding: 7px 12px; border-top: 1px solid #e8ece5; }
.call-participant-list span { padding: 4px 6px; border-radius: 10px; color: #647267; background: #f0f3ee; font-size: var(--type-caption); }
.call-local-camera-status { position: absolute; right: 16px; bottom: 16px; display: flex; align-items: center; gap: 5px; margin: 0; padding: 6px 8px; border-radius: 6px; color: #e5ebe5; background: rgba(0, 0, 0, .42); font-size: var(--type-small); }
.voice-room-dialog { width: min(1080px, calc(100vw - 32px)); height: min(760px, calc(100dvh - 32px)); max-height: none; border-color: #2d3b33; background: #111a15; }
.voice-room-dialog .call-dialog-header { border-color: #2b3930; background: #111a15; }
.voice-room-dialog .call-dialog-header .eyebrow { color: #9abda2; }
.voice-room-dialog .call-dialog-header h2 { color: #f0f4f0; }
.voice-room-dialog .call-connection { color: #bbc8bd; }
.voice-room-stage { min-height: 0 !important; grid-template-columns: repeat(auto-fit, minmax(min(210px, 100%), 240px)); grid-auto-rows: minmax(140px, 1fr); align-content: center; justify-content: center; gap: 12px; padding: 22px; background: #151f19; }
.call-voice-participant { display: flex; min-width: 0; min-height: 140px; align-items: center; justify-content: center; flex-direction: column; gap: 8px; padding: 14px; border: 1px solid #34443a; border-radius: 12px; color: #f0f4f0; background: #202c24; box-shadow: 0 5px 16px rgb(0 0 0 / 12%); }
.call-voice-participant.is-local { border-color: #628a6a; box-shadow: 0 0 0 1px rgb(98 138 106 / 24%); }
.call-voice-avatar-wrap { position: relative; margin-bottom: 3px; }
.avatar.call-voice-avatar { width: 68px; height: 68px; color: #23432d; background: #c9dfc8; font-size: var(--type-heading-sm); }
.call-voice-avatar img { width: 100%; height: 100%; object-fit: cover; }
.call-voice-mic { position: absolute; right: -3px; bottom: -2px; display: grid; width: 25px; height: 25px; place-items: center; border: 2px solid #202c24; border-radius: 50%; color: #17371e; background: #a4d3a5; }
.call-voice-mic.is-muted { color: #fff; background: #a54848; }
.call-voice-participant strong { max-width: 100%; overflow: hidden; font-size: var(--type-label); font-weight: 650; text-overflow: ellipsis; white-space: nowrap; }
.call-voice-participant small { color: #b4c0b7; font-size: var(--type-small); }
.voice-room-stage .call-room-waiting { grid-column: 1 / -1; max-width: none; margin: 0; color: #b4c0b7; text-align: center; }
.voice-room-dialog .call-controls { border-color: #2b3930; background: #111a15; }
.voice-room-dialog .call-controls button { min-height: 38px; padding: 8px 13px; border: 1px solid #36453b; border-radius: 9px; color: #eef3ef; background: #26352b; }
.voice-room-dialog .call-controls button:hover:not(:disabled) { background: #34483a; }
.voice-room-dialog .call-controls .call-end-button { border-color: #b44848; color: #fff; background: #b44848; }
.voice-room-dialog .call-controls .call-end-button:hover:not(:disabled) { background: #963838; }

@media (max-width: 700px) {
  .incoming-call-banner { z-index: 30; inset: 0; display: flex; align-items: center; flex-direction: column; justify-content: center; gap: 18px; padding: 28px; border: 0; border-radius: 0; background: rgba(16, 35, 27, .98); box-shadow: none; }
  .incoming-call-banner > .avatar { width: 76px; height: 76px; color: #47644c; background: #dce7d7; font-size: var(--type-display-sm); }
  .incoming-call-banner > div { align-items: center; flex: 0 0 auto; gap: 7px; text-align: center; }
  .incoming-call-banner strong { color: #f3f6f2; font-size: var(--type-heading-sm); }
  .incoming-call-banner small { color: #c6d1c8; font-size: var(--type-body-lg); }
  .incoming-call-banner > button { width: min(280px, 100%); min-height: 48px; border-radius: 10px; font-size: var(--type-body-lg); touch-action: manipulation; }
  .incoming-call-banner .decline-call-button { order: 1; }
  .call-dialog { max-height: calc(100svh - 24px); }
  .call-media-stage { min-height: 240px; padding: 8px; }
  .call-video-local { right: 18px; bottom: 84px; }
  .voice-room-dialog { width: calc(100vw - 16px); height: calc(100dvh - 16px); min-height: 0; border-radius: 12px; }
  .voice-room-stage { grid-template-columns: repeat(auto-fit, minmax(min(145px, 100%), 1fr)); grid-auto-rows: minmax(125px, 1fr); gap: 8px; padding: 12px; }
  .call-voice-participant { min-height: 125px; padding: 9px; }
  .avatar.call-voice-avatar { width: 56px; height: 56px; }
  .voice-room-dialog .call-dialog-header { padding: 10px 12px; }
  .conversation-header-actions { gap: 6px; }
}

/* P0-MEDIA-01: persistent encrypted image hydration + media viewer */
.attachment-image-button { display: block; max-width: min(340px, 100%); padding: 0; border: 0; border-radius: 7px; background: transparent; cursor: zoom-in; }
.attachment-image-button img { width: auto; max-width: 100%; min-width: 120px; min-height: 90px; }
.attachment-image-skeleton { display: grid; width: min(280px, 65vw); aspect-ratio: 4 / 3; place-items: center; align-content: center; gap: 7px; border-radius: 7px; color: #849087; background: linear-gradient(100deg, #eef1ec 20%, #f6f7f4 40%, #eef1ec 60%); background-size: 200% 100%; animation: media-shimmer 1.35s linear infinite; font-size: var(--type-small); }
.attachment-image-error { display: inline-flex; align-items: center; gap: 6px; padding: 8px 10px; border: 1px solid #ecd8d2; border-radius: 7px; color: #945449; background: #fff9f7; font: inherit; font-size: var(--type-small); cursor: pointer; }
@keyframes media-shimmer { to { background-position: -200% 0; } }
.media-viewer { position: fixed; z-index: 100; inset: 0; display: grid; grid-template-rows: 62px minmax(0, 1fr) 70px; color: #f3f6f3; background: rgba(10, 16, 13, .97); }
.media-viewer-header { display: flex; align-items: center; gap: 12px; padding: 9px 16px; border-bottom: 1px solid rgba(255,255,255,.08); }
.media-viewer-header > button, .media-viewer-footer > button, .media-viewer-nav { display: grid; width: 38px; height: 38px; place-items: center; flex: 0 0 auto; border: 0; border-radius: 50%; color: #eef3ee; background: rgba(255,255,255,.08); cursor: pointer; }
.media-viewer-header > div { display: flex; min-width: 0; flex: 1; flex-direction: column; gap: 2px; }
.media-viewer-header strong { font-size: var(--type-body-xs); font-weight: 600; }
.media-viewer-header small { color: #aeb8b0; font-size: var(--type-small); }
.media-viewer-stage { position: relative; display: grid; min-height: 0; place-items: center; overflow: hidden; }
.media-viewer-pan { display: grid; width: 100%; height: 100%; place-items: center; overflow: auto; }
.media-viewer-pan img { max-width: 92vw; max-height: calc(100svh - 160px); object-fit: contain; transform-origin: center; transition: transform .15s ease; }
.media-viewer-nav { position: absolute; z-index: 2; top: 50%; transform: translateY(-50%); }
.media-viewer-prev { left: 16px; }
.media-viewer-next { right: 16px; }
.media-viewer-loading, .media-viewer-error { display: flex; align-items: center; flex-direction: column; gap: 10px; color: #c6cec8; font-size: var(--type-label); }
.media-viewer-loading span { width: 28px; height: 28px; border: 2px solid rgba(255,255,255,.18); border-top-color: #e7eee8; border-radius: 50%; animation: media-spin .8s linear infinite; }
.media-viewer-error button { padding: 7px 10px; border: 0; border-radius: 6px; cursor: pointer; }
@keyframes media-spin { to { transform: rotate(360deg); } }
.media-viewer-footer { display: flex; align-items: center; justify-content: center; gap: 8px; padding: 8px 14px; border-top: 1px solid rgba(255,255,255,.08); }
.media-viewer-footer > span { min-width: 42px; color: #c1cac3; text-align: center; font-size: var(--type-small); }
.media-viewer-footer button:disabled { opacity: .35; cursor: default; }
.media-viewer-strip { display: flex; max-width: min(620px, 58vw); gap: 5px; overflow-x: auto; margin-left: 12px; }
.media-viewer-strip button { width: 62px; height: 42px; overflow: hidden; padding: 4px; border: 1px solid transparent; border-radius: 5px; color: #b9c2bb; background: rgba(255,255,255,.06); font: inherit; cursor: pointer; }
.media-viewer-strip button.active { border-color: #8fb08f; background: rgba(143,176,143,.16); }
.media-viewer-strip span { display: block; overflow: hidden; font-size: var(--type-micro); text-overflow: ellipsis; white-space: nowrap; }
@media (max-width: 760px) {
  .media-viewer { grid-template-rows: 56px minmax(0, 1fr) 58px; }
  .media-viewer-nav { width: 34px; height: 34px; }
  .media-viewer-prev { left: 6px; }
  .media-viewer-next { right: 6px; }
  .media-viewer-strip { display: none; }
  .media-viewer-pan img { max-width: 100vw; max-height: calc(100svh - 120px); }
}
@media (prefers-reduced-motion: reduce) { .attachment-image-skeleton, .media-viewer-loading span { animation: none; } }

/* P0-MEDIA-02: encrypted video messaging */
.attachment-video-play { position: absolute; inset: 50% auto auto 50%; display: grid; width: 42px; height: 42px; place-items: center; border-radius: 50%; background: rgba(9,18,13,.72); transform: translate(-50%,-50%); }
.media-viewer-video { width: min(92vw, 1200px); max-height: calc(100svh - 160px); background: #000; outline: none; }
@media (max-width: 760px) { .media-viewer-video { width: 100vw; max-height: calc(100svh - 120px); } }

.attachment-v2-video-ready { position: relative; display: grid; width: min(340px, 100%); min-height: 150px; place-items: center; align-content: center; gap: 6px; overflow: hidden; padding: 16px; border: 0; border-radius: 8px; color: #eef3ef; background: #15251e; font: inherit; cursor: pointer; }
.attachment-v2-video-ready:disabled { cursor: wait; }
.attachment-v2-video-ready .attachment-v2-video-poster { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.attachment-video-overlay { position: absolute; z-index: 1; inset: 0; pointer-events: none; }
