:root:is([data-theme], :not([data-theme])) .auth-form input:focus,
:root:is([data-theme], :not([data-theme])) .profile-form input:focus,
:root:is([data-theme], :not([data-theme])) .profile-form textarea:focus,
:root:is([data-theme], :not([data-theme])) .username-input:focus-within,
:root:is([data-theme], :not([data-theme])) .message-composer:focus-within { border-color: var(--color-focus-ring); box-shadow: 0 0 0 2px var(--color-focus-ring); }
:root:is([data-theme], :not([data-theme])) .overlay { background: var(--color-overlay); }
/* Secondary text is too faint on the approved message fills in Light mode. */
:root:is([data-theme], :not([data-theme])) .message-bubble .message-time,
:root:is([data-theme], :not([data-theme])) .message-bubble .message-edited { color: var(--color-text-primary); }
:root:is([data-theme], :not([data-theme])) .muted,
:root:is([data-theme], :not([data-theme])) .welcome-description,
:root:is([data-theme], :not([data-theme])) .workspace-footer,
:root:is([data-theme], :not([data-theme])) .workspace-footer button,
:root:is([data-theme], :not([data-theme])) .profile-form .profile-checkbox > span > small,
:root:is([data-theme], :not([data-theme])) .sessions-caption { color: var(--color-text-secondary); }
:root:is([data-theme], :not([data-theme])) .profile-form .profile-checkbox > input { accent-color: var(--color-primary); }
:root:is([data-theme], :not([data-theme])) .avatar-you,
:root:is([data-theme], :not([data-theme])) .chat-avatar,
:root:is([data-theme], :not([data-theme])) .profile-avatar { color: var(--color-text-primary); background: var(--color-primary-soft); }
:root:is([data-theme], :not([data-theme])) .navigation-badge { color: var(--color-on-primary); background: var(--color-danger); }
:root:is([data-theme], :not([data-theme])) .mobile-brand { color: var(--color-text-primary); }
